export function isInsideWindow( start: string, end: string, dayStart: string, dayEnd: string ): boolean {
  // your code here
  if (dayStart && dayEnd && dayStart.length !== dayEnd.length) {
    return false;
  }

  const startArray = start.split('-');
  const endArray = end.split('-');

  const startMonth = +startArray[1];
  const startDay = +startArray[2];
  const endMonth = +endArray[1];
  const endDay = +endArray[2];

  if (startMonth !== endMonth || startDay !== endDay) {
    return false;
  }

  return true;
}
